//! Property tests for the ported `chronon_divmod` splits.
//!
//! Two layers of evidence run on every `cargo test`:
//!
//! 1. `r_crosscheck_fixture_matches` replays `crosscheck.json`, which was
//!    generated by running the real R implementation on 120 day values,
//!    120 month values and 120 year values (100 integer + 20 fractional
//!    samples per unit), including multi-granule cases. This is the original
//!    480-value randomized cross-check, extended with the granule variants.
//! 2. The `prop_*` tests generate fresh inputs from the same ranges plus
//!    explicit month/quarter/leap-year edge values, and compare against an
//!    independent oracle built on `chrono` (different algorithm from the
//!    port), so arbitrary inputs are covered too.

use super::*;
use chrono::{Datelike, Duration, NaiveDate};
use proptest::prelude::*;
use serde::Deserialize;

const TOL: f64 = 1e-12;

fn view(x: &[f64]) -> ArrayView1<'_, f64> {
    ArrayView1::from(x)
}

fn epoch() -> NaiveDate {
    NaiveDate::from_ymd_opt(1970, 1, 1).unwrap()
}

fn day_offset(year: i32, month: u32, day: u32) -> f64 {
    (NaiveDate::from_ymd_opt(year, month, day).unwrap() - epoch()).num_days() as f64
}

fn month_index_to_ym(index: i64) -> (i64, i64) {
    let year = index.div_euclid(12) + 1970;
    let month = index - 12 * (year - 1970) + 1;
    (year, month)
}

fn month_start_offset(index: i64) -> f64 {
    let (year, month) = month_index_to_ym(index);
    day_offset(year as i32, month as u32, 1)
}

fn days_in_month(year: i64, month: i64) -> f64 {
    let (next_year, next_month) = if month == 12 {
        (year + 1, 1)
    } else {
        (year, month + 1)
    };
    month_start_offset((next_year - 1970) * 12 + (next_month - 1))
        - month_start_offset((year - 1970) * 12 + (month - 1))
}

// --- Independent chrono-based oracle ---------------------------------------

fn oracle_day_to_month(x: f64, from_n: f64, to_n: f64) -> (f64, f64) {
    let scaled = from_n * x;
    let x_int = scaled.floor();
    let x_frac = scaled - x_int;
    let date = epoch() + Duration::days(x_int as i64);
    let res = (date.year() as f64 - 1970.0) * 12.0 + (date.month() as f64 - 1.0);
    let div = (res / to_n).floor();
    let start = month_start_offset((div * to_n) as i64);
    (div, (x_int - start + x_frac) / from_n)
}

fn oracle_day_to_year(x: f64, from_n: f64) -> (f64, f64) {
    let scaled = from_n * x;
    let x_int = scaled.floor();
    let x_frac = scaled - x_int;
    let date = epoch() + Duration::days(x_int as i64);
    (
        date.year() as f64 - 1970.0,
        (date.ordinal0() as f64 + x_frac) / from_n,
    )
}

fn oracle_month_to_day(x: f64, from_n: f64, to_n: f64) -> (f64, f64) {
    let scaled = from_n * x;
    let x_int = scaled.floor();
    let x_frac = scaled - x_int;
    let (year, month) = month_index_to_ym(x_int as i64);
    let start = month_start_offset(x_int as i64);
    let dim = days_in_month(year, month);
    ((start + x_frac * dim) / to_n, 0.0)
}

fn oracle_year_to_day(x: f64, from_n: f64, to_n: f64) -> (f64, f64) {
    let scaled = from_n * x;
    let y_int = scaled.floor();
    let y_frac = scaled - y_int;
    let year = y_int as i64 + 1970;
    let start = day_offset(year as i32, 1, 1);
    let days_in_year = if NaiveDate::from_ymd_opt(year as i32, 2, 29).is_some() {
        366.0
    } else {
        365.0
    };
    ((start + y_frac * days_in_year) / to_n, 0.0)
}

// --- Strategies: original ranges + explicit edge values ---------------------

fn edge_days() -> Vec<f64> {
    vec![
        -1.0,
        0.0,
        1.0,
        day_offset(1969, 12, 31),
        day_offset(1970, 1, 31),
        day_offset(1970, 2, 1),
        day_offset(1970, 2, 28),
        day_offset(1970, 3, 1),
        day_offset(1900, 2, 28),
        day_offset(1900, 3, 1),
        day_offset(2000, 2, 28),
        day_offset(2000, 2, 29),
        day_offset(2000, 3, 1),
        day_offset(2024, 2, 28),
        day_offset(2024, 2, 29),
        day_offset(2024, 3, 1),
        day_offset(1970, 4, 1),
        day_offset(1970, 7, 1),
        day_offset(1970, 10, 1),
        day_offset(2026, 1, 1),
        day_offset(2026, 4, 1),
        day_offset(2026, 7, 1),
        day_offset(2026, 10, 1),
        31.25,
        59.5,
        90.75,
        365.5,
        366.25,
        -0.5,
        -31.25,
        -365.5,
    ]
}

fn edge_months() -> Vec<f64> {
    vec![
        -5000.0, -4999.0, -839.0, -13.0, -12.0, -11.0, -1.0, -0.5, 0.0, 0.5, 1.0, 2.0, 11.0, 12.0,
        13.0, 361.0, 599.0, 600.0, 601.0, 637.0, 649.0, 4999.0, 5000.0, -660.5, -100.25, 660.25,
        660.5,
    ]
}

fn edge_years() -> Vec<f64> {
    vec![
        -500.0, -499.0, -70.5, -70.0, -69.5, -1.5, -1.0, -0.5, 0.0, 0.5, 1.0, 29.0, 29.5, 30.0,
        30.5, 53.0, 54.0, 54.5, 55.0, 55.5, 56.0, 56.5, 130.0, 499.0, 500.0,
    ]
}

fn day_strategy() -> impl Strategy<Value = f64> {
    prop_oneof![
        (-100_000i64..=100_000i64).prop_map(|v| v as f64),
        (-1000.0f64..1000.0f64),
        proptest::sample::select(edge_days()),
    ]
}

fn month_strategy() -> impl Strategy<Value = f64> {
    prop_oneof![
        (-5000i64..=5000i64).prop_map(|v| v as f64),
        (-100.0f64..100.0f64),
        proptest::sample::select(edge_months()),
    ]
}

fn year_strategy() -> impl Strategy<Value = f64> {
    prop_oneof![
        (-500i64..=500i64).prop_map(|v| v as f64),
        (-10.0f64..10.0f64),
        proptest::sample::select(edge_years()),
    ]
}

fn from_n_12() -> impl Strategy<Value = f64> {
    prop_oneof![Just(1.0), Just(2.0)]
}

fn from_n_123() -> impl Strategy<Value = f64> {
    prop_oneof![Just(1.0), Just(2.0), Just(3.0)]
}

fn to_n_13() -> impl Strategy<Value = f64> {
    prop_oneof![Just(1.0), Just(3.0)]
}

fn to_n_12() -> impl Strategy<Value = f64> {
    prop_oneof![Just(1.0), Just(2.0)]
}

fn close(actual: f64, expected: f64) -> bool {
    (actual - expected).abs() <= TOL * expected.abs().max(1.0)
}

// --- Proptest properties ----------------------------------------------------

proptest! {
    #![proptest_config(ProptestConfig { cases: 480, .. ProptestConfig::default() })]

    #[test]
    fn prop_day_to_month_matches_oracle(
        x in day_strategy(),
        from_n in from_n_12(),
        to_n in to_n_13(),
    ) {
        let (div, modv) = day_to_month(view(&[x]), from_n, to_n);
        let (expected_div, expected_mod) = oracle_day_to_month(x, from_n, to_n);
        prop_assert!(close(div[0], expected_div), "div: {} vs {}", div[0], expected_div);
        prop_assert!(close(modv[0], expected_mod), "mod: {} vs {}", modv[0], expected_mod);
    }

    #[test]
    fn prop_day_to_year_matches_oracle(
        x in day_strategy(),
        from_n in from_n_12(),
    ) {
        let (div, modv) = day_to_year(view(&[x]), from_n, 1.0);
        let (expected_div, expected_mod) = oracle_day_to_year(x, from_n);
        prop_assert!(close(div[0], expected_div), "div: {} vs {}", div[0], expected_div);
        prop_assert!(close(modv[0], expected_mod), "mod: {} vs {}", modv[0], expected_mod);
    }

    #[test]
    fn prop_month_to_day_matches_oracle(
        x in month_strategy(),
        from_n in from_n_123(),
        to_n in to_n_12(),
    ) {
        let (div, modv) = month_to_day(view(&[x]), from_n, to_n);
        let (expected_div, expected_mod) = oracle_month_to_day(x, from_n, to_n);
        prop_assert!(close(div[0], expected_div), "div: {} vs {}", div[0], expected_div);
        prop_assert!(close(modv[0], expected_mod), "mod: {} vs {}", modv[0], expected_mod);
    }

    #[test]
    fn prop_year_to_day_matches_oracle(
        x in year_strategy(),
        from_n in from_n_12(),
        to_n in to_n_12(),
    ) {
        let (div, modv) = year_to_day(view(&[x]), from_n, to_n);
        let (expected_div, expected_mod) = oracle_year_to_day(x, from_n, to_n);
        prop_assert!(close(div[0], expected_div), "div: {} vs {}", div[0], expected_div);
        prop_assert!(close(modv[0], expected_mod), "mod: {} vs {}", modv[0], expected_mod);
    }
}

// --- Replay of the R-generated randomized cross-check ----------------------

#[derive(Deserialize)]
struct Crosscheck {
    inputs: CrosscheckInputs,
    cases: Vec<CrossCase>,
}

#[derive(Deserialize)]
struct CrosscheckInputs {
    days: Vec<f64>,
    months: Vec<f64>,
    years: Vec<f64>,
}

#[derive(Deserialize)]
struct CrossCase {
    name: String,
    from_n: f64,
    to_n: f64,
    input: Vec<f64>,
    div: Vec<f64>,
    #[serde(rename = "mod")]
    remainder: Vec<f64>,
}

fn dispatch(name: &str, x: &[f64], from_n: f64, to_n: f64) -> (Vec<f64>, Vec<f64>) {
    match name {
        "day_to_month" | "day_to_quarter" | "twoday_to_month" => {
            day_to_month(view(x), from_n, to_n)
        }
        "day_to_year" | "twoday_to_year" => day_to_year(view(x), from_n, to_n),
        "month_to_day" | "bimonth_to_day" | "month_to_2day" => month_to_day(view(x), from_n, to_n),
        "year_to_day" | "year_to_2day" => year_to_day(view(x), from_n, to_n),
        other => panic!("unknown crosscheck case: {other}"),
    }
}

fn assert_close(actual: &[f64], expected: &[f64], label: &str) {
    assert_eq!(actual.len(), expected.len(), "{label}: length mismatch");
    for (i, (a, e)) in actual.iter().zip(expected).enumerate() {
        assert!(close(*a, *e), "{label}[{i}]: rust={a} r={e}");
    }
}

#[test]
fn r_crosscheck_fixture_matches() {
    let data: Crosscheck = serde_json::from_str(include_str!("../../fixtures/crosscheck.json"))
        .expect("crosscheck.json must parse");

    assert_eq!(data.inputs.days.len(), 120);
    assert_eq!(data.inputs.months.len(), 120);
    assert_eq!(data.inputs.years.len(), 120);
    assert_eq!(data.cases.len(), 10);

    for case in &data.cases {
        let (div, modv) = dispatch(&case.name, &case.input, case.from_n, case.to_n);
        assert_close(&div, &case.div, &format!("{} div", case.name));

        // R returns a length-1 `mod` for the inverse conversions and recycles
        // it across the result vector.
        let expected_mod = if case.remainder.len() == 1 && case.input.len() > 1 {
            vec![case.remainder[0]; case.input.len()]
        } else {
            case.remainder.clone()
        };
        assert_close(&modv, &expected_mod, &format!("{} mod", case.name));
    }
}

#[test]
#[should_panic(expected = "Converting to non-year chronons")]
fn day_to_year_rejects_multi_year_targets() {
    let _ = day_to_year(view(&[0.0]), 1.0, 2.0);
}

/// The benchmark scripts generate inputs with this LCG. These first values were
/// produced by the R script (`benchmarks/bench.R`) and pin both
/// sides to the same vectors.
#[test]
fn benchmark_lcg_matches_r() {
    fn lcg(n: usize, modulus: u64, offset: f64) -> Vec<f64> {
        (0..n)
            .map(|i| {
                let v = ((i as u64).wrapping_mul(1_103_515_245).wrapping_add(12_345)
                    % (1u64 << 31))
                    % modulus;
                v as f64 - offset
            })
            .collect()
    }

    assert_eq!(
        lcg(5, 200_001, 100_000.0),
        vec![-87655.0, 22073.0, 58890.0, -31383.0, 5434.0]
    );
    assert_eq!(
        lcg(5, 10_001, 5_000.0),
        vec![-2656.0, 2249.0, -1768.0, 3137.0, -880.0]
    );
    assert_eq!(
        lcg(5, 1_001, 500.0),
        vec![-167.0, -335.0, 188.0, 20.0, -458.0]
    );
}
